-- Multiverse Portal RPG: 5 scenarios + 60 characters (plan 2026-10-26)
insert into public.game_scenarios (id, game, seq, title, inspiration, story, setting, stages, class_plan, asset_ids,
  rounds, minutes_per_round, character_count, active, plan_version)
select e->>0, 'multiverse_portal', (e->>1)::smallint, e->>2, e->>3, e->>4, e->>5, e->6, e->7,
  array(select jsonb_array_elements_text(e->8)), 6, 5, 12, true, 2
from jsonb_array_elements($j$[["mv-01",1,"Lâu Đài Sương Mù","File mục I.2 (nữ chiến binh 3D, diệt Boss mở cổng Stencil Portal); thế giới lâu đài sương mù đã có.","Chúa Tể Vết Nứt đã đánh cắp Cuốn Sách Ngôn Từ, khiến chữ nghĩa trong vương quốc bắt đầu biến mất. Nữ chiến binh Scarlet cùng các bạn lần theo hắn vào Lâu Đài Sương Mù. Mỗi đòn đánh trúng làm rơi một trang sách, và mỗi trang mang một từ được cứu lại. Khi Chúa Tể yếu đi, hắn xé rách không gian và bỏ chạy qua vết nứt sang một thế giới khác. Scarlet phải lấy lại đủ trang sách trước khi chuông lâu đài điểm 12 tiếng.","Lâu đài gothic đổ nát trên đảo bay, sương tím phủ lối đá, cửa sổ kính màu vỡ, đèn ma trơi xanh. Tiếng chuông xa vọng lại.",[{"n":1,"title":"Cổng lâu đài","minutes":5,"optional":false,"goal":"Vào lâu đài, gặp lính canh sương.","beats":["Lính canh làm bằng sương, tan khi trúng đòn."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Mở cổng.","vocab":["castle","gate","fog"],"assets":["mv_world_castle","mv_hero_scarlet"]},{"n":2,"title":"Hành lang kính màu","minutes":5,"optional":false,"goal":"Đánh bóng ma trên hành lang.","beats":["Mỗi trang sách rơi ra một từ."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Trang sách 1-3.","vocab":["page","word","save"],"assets":["mv_world_castle"]},{"n":3,"title":"Chúa Tể xuất hiện","minutes":5,"optional":false,"goal":"Đối đầu Chúa Tể Vết Nứt pha 1.","beats":["Thanh máu Boss lớn."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Chí mạng mở Kỹ năng.","vocab":["boss","attack","shield"],"assets":["mv_boss"]},{"n":4,"title":"Pha 2: Cơn thịnh nộ","minutes":5,"optional":false,"goal":"Boss dưới 50%: đổi dạng, đánh mạnh hơn.","beats":["Sai 3 câu liền: Boss nổi giận, gợi ý sâu hơn."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Kỹ năng Mắt Sự Thật.","vocab":["angry","phase","strong"],"assets":["mv_boss","fx_spark"]},{"n":5,"title":"Vết nứt mở","minutes":5,"optional":false,"goal":"Boss xé không gian bỏ chạy: Scarlet nhảy theo qua cổng.","beats":["Hiệu ứng cổng Stencil."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Thế giới mới hé lộ.","vocab":["portal","jump","chase"],"assets":["mv_world_cyberpunk"]},{"n":6,"title":"Chuông 12 tiếng","minutes":5,"optional":false,"goal":"Đánh bại Boss, lấy lại Cuốn Sách Ngôn Từ.","beats":["Chữ nghĩa trở lại vương quốc."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Danh hiệu \"Người Giữ Sách\".","vocab":["victory","book","return"],"assets":["mv_world_castle","anim_cheer"]},{"n":7,"title":"Chặng phụ: Thư viện tầng hầm","minutes":5,"optional":true,"goal":"Kéo dài: đánh lính sương trong thư viện.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["library","shelf"],"assets":["mv_world_castle"]},{"n":8,"title":"Chặng phụ: Viết lại trang sách","minutes":5,"optional":true,"goal":"Viết lại một trang sách bằng câu của mình.","beats":["Trang sách in vào hồ sơ học viên."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.","reward":"Huy hiệu \"Nhà Văn Lâu Đài\".","vocab":["once upon a time","hero"],"assets":["mv_world_castle"]}],{},["anim_cheer","fx_spark","mv_boss","mv_hero_scarlet","mv_world_castle","mv_world_cyberpunk"]],["mv-02",2,"Thành Phố Neon Đêm Mưa","Thế giới cyberpunk neon đã có trong manifest; cổng không gian.","Chạy qua vết nứt, Chúa Tể Vết Nứt trốn vào Thành Phố Neon và chiếm tháp truyền tin. Hắn đổi chữ trên mọi bảng hiệu thành mật mã, làm người dân lạc đường. Scarlet và tổ đội phải nhảy qua mái nhà, sửa bảng hiệu bằng câu trả lời đúng và leo lên tháp. Trên đỉnh tháp, Chúa Tể triệu hồi robot bảo vệ, rồi lại xé không gian định trốn sang sa mạc. Lần này Scarlet có Kỹ năng Khóa Cổng, nếu chuỗi đúng đủ dài.","Thành phố tương lai đêm mưa, bảng neon hồng xanh, xe bay, mái nhà ướt phản chiếu ánh đèn. Tiếng mưa và nhạc điện tử xa.",[{"n":1,"title":"Hẻm neon","minutes":5,"optional":false,"goal":"Đáp xuống hẻm neon, sửa bảng hiệu đầu tiên.","beats":["Bảng hiệu sáng đúng chữ."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Bản đồ thành phố.","vocab":["city","sign","neon"],"assets":["mv_world_cyberpunk","mv_hero_scarlet"]},{"n":2,"title":"Mái nhà mưa","minutes":5,"optional":false,"goal":"Nhảy qua mái nhà, tránh drone.","beats":["Drone soi đèn đỏ."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Giày phản lực.","vocab":["jump","roof","rain"],"assets":["mv_world_cyberpunk"]},{"n":3,"title":"Robot bảo vệ","minutes":5,"optional":false,"goal":"Đánh robot bảo vệ tháp.","beats":["Robot có khiên năng lượng."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Phá khiên.","vocab":["robot","shield","break"],"assets":["mv_boss"]},{"n":4,"title":"Đỉnh tháp","minutes":5,"optional":false,"goal":"Đối đầu Chúa Tể pha 1.","beats":["Mưa tạo sấm khi chí mạng."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Chí mạng sấm.","vocab":["tower","top","thunder"],"assets":["mv_boss","fx_spark"]},{"n":5,"title":"Pha 2 và Khóa Cổng","minutes":5,"optional":false,"goal":"Boss dưới 50% mở cổng; chuỗi 5 câu đúng khóa cổng 20 giây.","beats":["Khóa thành công = sát thương gấp đôi."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Kỹ năng Khóa Cổng.","vocab":["lock","chain","combo"],"assets":["mv_boss","mv_world_desert"]},{"n":6,"title":"Thành phố sáng lại","minutes":5,"optional":false,"goal":"Đánh bại Chúa Tể, mọi bảng hiệu sáng đúng chữ.","beats":["Pháo hoa neon."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Danh hiệu \"Anh Hùng Neon\".","vocab":["light","city","saved"],"assets":["mv_world_cyberpunk","anim_cheer"]},{"n":7,"title":"Chặng phụ: Đường đua xe bay","minutes":5,"optional":true,"goal":"Kéo dài: đuổi Quạ Tím bằng xe bay.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["fly","chase"],"assets":["mv_world_cyberpunk"]},{"n":8,"title":"Chặng phụ: Bảng hiệu của em","minutes":5,"optional":true,"goal":"Thiết kế một bảng hiệu tiếng Anh cho thành phố.","beats":["Bảng hiệu treo trong game."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.","reward":"Huy hiệu \"Nhà Thiết Kế Neon\".","vocab":["open","welcome","shop"],"assets":["mv_world_cyberpunk"]}],{},["anim_cheer","fx_spark","mv_boss","mv_hero_scarlet","mv_world_cyberpunk","mv_world_desert"]],["mv-03",3,"Tàn Tích Sa Mạc Cát Vàng","Thế giới sa mạc tàn tích trong manifest; cổng không gian.","Vết nứt cuối cùng đưa Chúa Tể Vết Nứt đến Tàn Tích Sa Mạc, nơi chôn Đá Ngữ Pháp cổ. Nếu hắn chạm được viên đá, mọi câu văn trong đa vũ trụ sẽ đảo lộn trật tự. Scarlet phải vượt bão cát, giải câu đố trên các bức tượng đá để mở cửa kim tự tháp trước hắn. Trong lòng kim tự tháp, những bậc thang chỉ hiện ra khi câu được sắp xếp đúng trật tự. Trận cuối diễn ra quanh Đá Ngữ Pháp, mỗi đòn đúng làm viên đá sáng lên che chở Scarlet.","Sa mạc cát vàng, kim tự tháp đổ nát, tượng đá khổng lồ vùi nửa người trong cát, ốc đảo xanh xa xa. Nắng gắt, bão cát nổi lên từng đợt. Giữa bão cát thấp thoáng một cù lao xanh có cọ và gốc cây cổ: ốc đảo thật.",[{"n":1,"title":"Bão cát","minutes":5,"optional":false,"goal":"Vượt bão cát đến tàn tích.","beats":["Cát che tầm nhìn, câu đúng soi đường."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Khăn che cát.","vocab":["desert","sand","storm"],"assets":["mv_world_desert","mv_hero_scarlet"]},{"n":2,"title":"Tượng đá","minutes":5,"optional":false,"goal":"Giải câu đố trên tượng đá.","beats":["Tượng mở mắt khi trả lời đúng.","Tấm đá cát nằm nghiêng làm bục đứng cho tượng đá; đặt đúng chữ thì tượng mới nhúc nhích."],"question_hook":"Câu đố khắc trên tượng; đúng = tượng nhường đường.","reward":"Chìa khóa kim tự tháp.","vocab":["statue","riddle","ancient","slab","sand"],"assets":["mv_world_desert","ground_sand_slab"]},{"n":3,"title":"Bậc thang trật tự","minutes":5,"optional":false,"goal":"Sắp xếp câu đúng để bậc thang hiện ra.","beats":["Hợp câu sắp xếp (reorder)."],"question_hook":"Mỗi câu xếp đúng hiện một bậc thang.","reward":"Lên tầng trên.","vocab":["order","stairs","climb"],"assets":["mv_world_desert"]},{"n":4,"title":"Chúa Tể pha 1","minutes":5,"optional":false,"goal":"Đối đầu Chúa Tể quanh Đá Ngữ Pháp.","beats":["Đá sáng lên theo đòn đúng."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Khiên Đá Ngữ Pháp.","vocab":["grammar","stone","glow"],"assets":["mv_boss"]},{"n":5,"title":"Pha 2: Bọ cạp cát","minutes":5,"optional":false,"goal":"Boss triệu hồi bọ cạp cát khổng lồ.","beats":["Bọ cạp chặn đòn; trinh sát tìm điểm yếu."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Chí mạng điểm yếu.","vocab":["scorpion","weak point"],"assets":["mv_boss","fx_spark"]},{"n":6,"title":"Ốc đảo","minutes":5,"optional":false,"goal":"Đánh bại Boss, đem Đá Ngữ Pháp về ốc đảo an toàn.","beats":["Cát lặng, ốc đảo nở hoa.","Ốc đảo hiện lên giữa cát: đúng câu thì cọ xanh trở lại."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Danh hiệu \"Người Giữ Đá Ngữ Pháp\".","vocab":["oasis","peace","win","palm tree"],"assets":["mv_world_desert","anim_cheer","mini_large_island"]},{"n":7,"title":"Chặng phụ: Lạc đà","minutes":5,"optional":true,"goal":"Kéo dài: cưỡi lạc đà đuổi Quạ Tím.","beats":["Câu nhanh."],"question_hook":"Câu hỏi hiện thành ấn phép trên kiếm của Scarlet như trận chính. Câu khó hơn một bậc, sao nhân đôi.","reward":"Sao đôi.","vocab":["camel","ride"],"assets":["mv_world_desert"]},{"n":8,"title":"Chặng phụ: Bia đá mới","minutes":5,"optional":true,"goal":"Khắc một câu đúng ngữ pháp lên bia đá.","beats":["Bia đá đặt ở ốc đảo."],"question_hook":"Mỗi em viết hoặc chọn câu tiếng Anh của mình trên trang sách phép. Câu viết, không tính thua.","reward":"Huy hiệu \"Nhà Khảo Cổ Nhí\".","vocab":["carve","sentence"],"assets":["mv_world_desert"]}],{},["anim_cheer","fx_spark","ground_sand_slab","mini_large_island","mv_boss","mv_hero_scarlet","mv_world_desert"]],["mv-04",4,"Cổng Vỡ Đuổi Bắt","Cổng Stencil xé không gian; chuyển cảnh mượt giữa lâu đài và thành phố neon.","Chúa Tể Vết Nứt học được cách mở nhiều cổng cùng lúc, và hai thế giới lâu đài và thành phố neon bắt đầu va vào nhau. Scarlet phải đuổi theo hắn qua những mảnh thế giới trôi nổi, mỗi lần nhảy cổng là sang một thế giới khác. Cổng chỉ đứng yên khi tổ đội trả lời đúng, sai thì cổng rung và đổi chỗ. Giữa đường, Quạ Tím bày bẫy cổng giả dẫn sang chỗ không lối thoát. Đóng được cổng cuối, hai thế giới sẽ tách ra và Chúa Tể bị kẹt giữa.","Không gian nứt vỡ: một nửa là lâu đài sương mù, một nửa là thành phố neon, các mảnh thế giới trôi lơ lửng nối nhau bằng cầu ánh sáng. Một đảo xanh nhỏ có sông và hải đăng trôi lạc giữa các mảnh vỡ.",[{"n":1,"title":"Mảnh lâu đài","minutes":5,"optional":false,"goal":"Bắt đầu ở mảnh lâu đài trôi nổi.","beats":["Cầu ánh sáng hiện theo câu đúng."],"question_hook":"Câu hỏi hiện thành ấn phép trên lưỡi kiếm của Scarlet; trả lời đúng là một đòn chém (đúng nhanh = chí mạng), sai thì Boss phản đòn nhẹ. Boss yếu đi 50% thì vết nứt không gian mở sang thế giới mới.","reward":"Cầu ánh sáng.","vocab":["bridge","float","light"],"assets":["mv_world_castle"]},{"n":2,"title":"Nhảy cổng 1","minute